'use strict';
// Three destinations. Source management is a setting, not a fourth destination.
navs.splice(0,navs.length,['today','home','待办'],['library','books','资料库'],['settings','settings','设置']);
function sourceScope(){return `<div class="scope-row"><span>${state.enabled.length?'仅处理 '+state.enabled.length+' 个已选来源':'尚未选择信息源'}</span>${button('navigate','选择来源','text small','data-page="sources"')}</div>`;}
function sourceEmpty(){return `<div class="empty source-empty">${icon('source')}<h3>只看你关心的来源</h3><p>选择需要处理的群聊或公众号，<br>机会和摘要会集中出现在这里。</p>${button('navigate','选择信息源','primary','data-page="sources"')}<small>当前为手动导入演示，尚未连接真实账号。</small></div>`;}
homeTabs=function(){return `<nav class="workspace-tabs" aria-label="信息内容切换">${[['today','事项',liveItems().length],['digest','摘要',selectedDigests().length]].map(([id,t,n])=>`<button class="workspace-tab ${page===id||id==='today'&&page==='opportunities'?'active':''}" data-action="navigate" data-page="${id}" aria-current="${page===id||id==='today'&&page==='opportunities'?'page':'false'}">${t}<small>${n}</small></button>`).join('')}</nav>`;};
header=function(eye,title,subtitle,actions=''){
  const information=['today','opportunities','digest'].includes(page);
  const titles={today:'Sift',opportunities:'Sift',digest:'Sift',library:showTrash?'最近删除':selectedCollection?state.brain.collections.find(c=>c.id===selectedCollection)?.name:'资料库',watch:'稍后看',settings:'设置',sources:'信息来源','campus-saved':'校园收藏'};
  const subtitles={today:'从通知到行动，少漏一件事。',opportunities:'从通知到行动，少漏一件事。',digest:'从通知到行动，少漏一件事。',library:'保存有用内容，需要时快速找到。',watch:'留待阅读的内容。',settings:'管理来源、机会类型和本地数据。',sources:'只处理你主动选择的来源。','campus-saved':'已保存的机会和摘要，关闭来源后仍保留。'};
  return `<div class="page-heading"><div><h1>${esc(titles[page]||title)}</h1><p class="page-subtitle">${esc(subtitles[page]||subtitle)}</p></div><div class="heading-buttons">${actions}</div></div>${information?sourceScope()+homeTabs():''}`;
};
const originalOpportunities=opportunitiesView;
opportunitiesView=function(){if(!state.enabled.length)return header('','','')+sourceEmpty();return originalOpportunities();};
todayView=function(){return opportunitiesView();};
digestView=function(){const items=selectedDigests();return header('','','',state.enabled.length?button('simulate',icon('plus')+'导入消息','primary')+(items.length?button('export-digest','导出','small secondary-heading'):''):'')+(state.enabled.length?`<p class="feed-note">示例摘要与手动导入摘录 · 未接入大模型</p><div class="digest-list">${items.map(digestCard).join('')||'<div class="empty"><h3>暂无摘要</h3><p>调整来源的处理方式，或导入指定来源的内容。</p></div>'}</div>`:sourceEmpty());};
sourcesView=function(){return header('','','',button('navigate','完成','primary','data-page="today"'))+`<p class="feed-note">开关即时生效。未选来源不会分析，也不会出现在信息流中。</p><div class="source-list">${sources.map(s=>{const enabled=state.enabled.includes(s.id);return `<article class="source-card"><div class="source-card-top"><span class="source-logo ${esc(s.kind)}">${esc(s.glyph)}</span><div class="source-name"><h3>${esc(s.name)}</h3><span class="sub">${esc(s.platform)} · ${s.custom?'手动导入':'示例'}</span></div><button class="switch ${enabled?'on':''}" role="switch" aria-checked="${enabled}" aria-label="选择${esc(s.name)}" data-action="source-toggle" data-id="${esc(s.id)}"></button></div>${enabled?`<label class="source-mode">处理方式<select data-source-mode="${esc(s.id)}" aria-label="${esc(s.name)}的处理方式">${Object.entries(ScopeCore.modes).map(([id,name])=>`<option value="${id}" ${(state.sourceModes[s.id]||'both')===id?'selected':''}>${name}</option>`).join('')}</select></label>`:''}</article>`;}).join('')}</div><div class="source-add">${button('add-source',icon('plus')+'添加自己的来源')}<p class="field-hint">填写名称用于归类导入内容；不会自动连接或读取该账号。</p></div><details class="source-boundary"><summary>接入状态与处理记录</summary><p class="field-hint">真实微信、QQ 和公众号采集尚未接入。手动粘贴内容在本地处理，摘要为原文摘录，提醒仅在页面内显示。</p>${state.logs.slice(0,6).map(l=>`<div class="log-entry"><time>${esc(l.time)}</time><div><strong>${esc(l.title)}</strong><p>${esc(l.detail)}</p></div></div>`).join('')||'<p class="field-hint">暂无处理记录。</p>'}</details>`;};
settingsView=function(){return header('','','')+`<div class="digest-main"><section class="setting-box"><div class="setting-row"><span><h3>信息来源</h3><small>已选 ${state.enabled.length} 个 · 未连接真实采集</small></span>${button('navigate','管理信息来源','small','data-page="sources"')}</div></section><form id="focus-prefs"><section class="setting-box"><h3>关注的机会</h3><p class="sub">只展示这些类型的机会；摘要不受此项影响。</p><div class="checkboxes">${Object.entries(C.TYPES).map(([v,t])=>`<label><input name="types" type="checkbox" value="${v}" ${state.prefs.types.includes(v)?'checked':''}>${t}</label>`).join('')}</div><div class="setting-row"><span><p>发现新机会时提示</p><small>手动导入时在页面内提示</small></span><input type="checkbox" name="instant" ${state.prefs.instant?'checked':''} aria-label="发现新机会时提示"></div><button type="submit" class="btn primary small">保存偏好</button></section></form><section class="setting-box"><h3>本地数据</h3><p class="sub">收藏和设置保存在当前浏览器，暂不跨设备同步。</p><div class="setting-row"><span>导出收藏与设置</span>${button('export','导出','small')}</div><div class="setting-row"><span>恢复初始演示</span>${button('reset-confirm','重置','small danger')}</div></section></div>`;};
simulation=function(){lastResult=null;const allowed=sources.filter(s=>state.enabled.includes(s.id));if(!allowed.length){page='sources';render();toast('先选择需要处理的来源');return;}showModal(`<h2 id="modal-title">导入消息</h2><p class="modal-description">仅处理已选来源。本地规则提取机会，内容摘要为原文摘录，不读取真实聊天。</p><form id="message-form"><label class="field">信息来源<select name="source">${allowed.map(s=>`<option value="${esc(s.id)}">${esc(s.name)} · ${ScopeCore.modes[state.sourceModes[s.id]||'both']}</option>`).join('')}</select></label><label class="field">消息或文章正文<textarea name="message" maxlength="4000" required placeholder="粘贴指定群聊的消息，或公众号文章正文…"></textarea></label><p class="field-hint">机会日期按演示年 2026 解析；请先用测试内容体验。</p><button type="submit" class="btn primary">处理内容</button></form><details class="source-boundary"><summary>试一条示例消息</summary><div class="sample-list">${samples.filter(s=>state.enabled.includes(s.source)).map(s=>`<button class="sample-btn" data-action="sample" data-id="${s.id}"><span>${s.symbol}</span><span><strong>${esc(s.name)}</strong><small>${esc(sourceName(s.source))}</small></span></button>`).join('')||'<p class="field-hint">这个来源暂无预置消息，请手动粘贴。</p>'}</div></details><div id="simulation-result" aria-live="polite"></div>`);};
function addSource(){showModal(`<h2 id="modal-title">添加信息来源</h2><p class="modal-description">建立一个你指定的来源，用于归类手动导入的内容。</p><form id="source-form"><label class="field">平台<select name="platform"><option value="wechat">微信群</option><option value="qq">QQ 群</option><option value="web">公众号</option></select></label><label class="field">群聊或公众号名称<input name="name" maxlength="40" required placeholder="例如：学院青年志愿者群"></label><label class="field">处理方式<select name="mode">${Object.entries(ScopeCore.modes).map(([id,n])=>`<option value="${id}">${n}</option>`).join('')}</select></label><p class="field-hint">添加后默认选中。名称仅用于标记来源，不代表已连接账号。</p><p id="source-error" role="alert" class="form-error"></p><button type="submit" class="btn primary">添加并选中</button></form>`);}
const cardBeforeFocus=card;
card=function(item){return cardBeforeFocus(['today','opportunities'].includes(page)?{...item,sources:item.sources.filter(id=>ScopeCore.allows(state,sources,id,'opportunities'))}:item);};
const builtInSources=sources.filter(s=>!s.custom);
const renderBeforeFocus=render;
render=function(){ScopeCore.migrate(state,builtInSources);sources.splice(0,sources.length,...builtInSources,...state.customSources);renderBeforeFocus();const active=['today','opportunities','digest'].includes(page)?'today':['library','watch','campus-saved'].includes(page)?'library':'settings';for(const n of document.querySelectorAll('#nav .nav-item')){n.classList.toggle('active',n.dataset.page===active);if(n.dataset.page===active)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');}$('#floating-capture').hidden=true;};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b?.dataset.action==='add-source')addSource();});
document.addEventListener('change',e=>{const id=e.target.dataset.sourceMode;if(id&&sources.some(s=>s.id===id)&&ScopeCore.modes[e.target.value]){state.sourceModes[id]=e.target.value;persist();render();}});
document.addEventListener('submit',e=>{
  if(e.target.id==='focus-prefs'){e.preventDefault();const fd=new FormData(e.target);state.prefs.types=fd.getAll('types');state.prefs.instant=fd.has('instant');persist();toast('偏好已保存');}
  if(e.target.id==='source-form'){e.preventDefault();const fd=new FormData(e.target),name=String(fd.get('name')||'').trim(),kind=fd.get('platform'),mode=fd.get('mode');if(!name||!['wechat','qq','web'].includes(kind)||!ScopeCore.modes[mode])return;
    if(sources.some(s=>s.name===name&&s.kind===kind)){$('#source-error').textContent='这个来源已存在，请在列表中选择。';return;}
    const s={id:crypto.randomUUID(),name,kind,platform:{wechat:'微信 · 群消息',qq:'QQ · 群消息',web:'公众号'}[kind],glyph:{wechat:'微',qq:'Q',web:'文'}[kind],custom:true};
    sources.push(s);state.customSources.push(s);state.enabled.push(s.id);state.sourceModes[s.id]=mode;persist();closeModal();page='sources';render();toast('来源已添加，可手动导入内容');
  }
});
persist();render();
